            }
        } else {
            _fundToken(address(token_), detfUser, amt);
            vm.prank(detfUser);
            token_.approve(d, amt);
        }
        vm.prank(detfUser);
        (tokenId, shares) = IUniswapV4Detf(d).bond(token_, amt, DEFAULT_MIN_LOCK, detfUser, false, _deadline());
        if (first_) _policyInitialBond[d] = tokenId;
